def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        if hp <= 2 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    cindy_prev = None
    pressure_count = 0
    needy_opponents = 0
    rich_opponents = 0

    for opp in alive:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            needy_opponents += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_opponents += 1
        prev = opp.get('previous_trace', {})
        bid = None
        if isinstance(prev, dict):
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= DAILY_SALARY * 0.75:
                pressure_count += 1
        if opp.get('daily_salary') == 70 and opp.get('water_requirement') == 13:
            if opp.get('budget', 0) > 200:
                cindy_prev = bid if bid is not None else cindy_prev

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    low_supply = supply <= 17
    mid_supply = supply <= 20
    emergency = hp <= 2 or no_water_days >= 2
    caution = hp <= 4 or no_water_days >= 1

    bid = DAILY_SALARY * 0.38

    if emergency:
        if low_supply:
            bid = DAILY_SALARY * 0.96
        elif mid_supply:
            bid = DAILY_SALARY * 0.88
        else:
            bid = DAILY_SALARY * 0.8
    elif caution:
        if highest_prev >= DAILY_SALARY * 0.85:
            bid = DAILY_SALARY * 0.72
        elif low_supply:
            bid = max(DAILY_SALARY * 0.62, highest_prev + 2.0)
        else:
            bid = max(DAILY_SALARY * 0.52, avg_prev + 1.5)
    else:
        if low_supply:
            bid = max(DAILY_SALARY * 0.58, highest_prev + 1.0)
        elif mid_supply:
            bid = max(DAILY_SALARY * 0.46, avg_prev + 1.0)
        else:
            bid = DAILY_SALARY * 0.34
            if highest_prev > 0:
                bid = max(bid, min(DAILY_SALARY * 0.5, highest_prev * 0.72))

    if cindy_prev is not None:
        if cindy_prev >= 150 and not emergency:
            bid = min(bid, DAILY_SALARY * 0.55)
        elif cindy_prev <= DAILY_SALARY * 0.6 and (caution or low_supply):
            bid = max(bid, cindy_prev + 1.5)

    if pressure_count >= 2 and not emergency:
        bid *= 0.92
    if needy_opponents >= 2 and (caution or low_supply):
        bid = max(bid, DAILY_SALARY * 0.68)
    if rich_opponents == 0 and not caution:
        bid *= 0.9

    remaining_days_factor = max(0, 10 - day)
    reserve_target = remaining_days_factor * DAILY_SALARY * 0.28
    if budget < reserve_target and not emergency:
        bid = min(bid, DAILY_SALARY * 0.48)

    bid = max(0.0, bid)
    bid = min(bid, budget)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    # Estimate how many water units are likely needed to survive remaining days.
    # We only act on immediate pressure from yesterday's trace.

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opps.append(o)

    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read yesterday's bids from immediate previous_trace.
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace') or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Determine competitive pressure.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    # Supply-based urgency: higher supply reduces the need to overbid.
    # Convert supply into a coarse tier.
    supply_tier = 0
    if supply <= MIN_SUPPLY + 1e-9:
        supply_tier = 2  # tight
    elif supply < MAX_SUPPLY - 1e-9:
        supply_tier = 1  # medium
    else:
        supply_tier = 0  # ample

    # Base bid target.
    # If yesterday pressure was high (Cindy/Alex), we bid slightly above the likely runner-up.
    # Otherwise, bid around a fraction of daily salary.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Competitive day: try to secure water without draining budget.
        # If our HP is low, we must ensure allocation; bid closer to highest_prev_bid.
        if my_hp <= 2.0:
            target = highest_prev_bid + 2.0
        else:
            # bid above second-highest to win but not fully match highest
            target = max(highest_prev_bid * 0.92, second_prev_bid + 2.0)
    else:
        # Not extremely pressured: bid based on supply tier and our HP.
        if my_hp <= 2.0:
            target = DAILY_SALARY * (0.75 if supply_tier >= 1 else 0.6)
        else:
            target = DAILY_SALARY * (0.55 if supply_tier == 0 else (0.65 if supply_tier == 1 else 0.72))

    # Safety caps: don't bid more than budget, and avoid irrational overbids.
    # Also, if budget is too low, bid proportionally.
    if my_budget <= 0:
        return 0.0

    # Prevent spending beyond what is likely needed for remaining days.
    # We don't know remaining days exactly, but no_water_days indicates risk.
    no_water_days = int(my_status.get('no_water_days', 0) or 0)
    risk_multiplier = 1.0
    if no_water_days >= 2:
        risk_multiplier = 1.25
    elif no_water_days == 1:
        risk_multiplier = 1.1

    # Final target with risk and supply adjustments.
    target = target * risk_multiplier

    # Hard cap relative to daily salary and budget.
    hard_cap = DAILY_SALARY * (0.95 if my_hp <= 2.0 else 0.8)
    target = min(target, hard_cap)

    # If supply is tight, we slightly increase willingness.
    if supply_tier == 2:
        target = min(target * 1.05, hard_cap)

    bid = min(my_budget, target)
    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    # Identify Alex and his previous bid
    alex_status = opponents_status.get('Alex')
    alex_yesterday_bid = 0
    if alex_status and alex_status['alive']:
        alex_prev_trace = alex_status.get('previous_trace')
        if alex_prev_trace and alex_prev_trace.get('bid') is not None:
            alex_yesterday_bid = alex_prev_trace['bid']

    # Calculate how many full water requirements can be met by current supply
    potential_winners = int(day_context['supply'] // WATER_REQ)

    # Base bid, usually a portion of daily salary
    base_bid = DAILY_SALARY * 0.8

    # --- Bidding Logic ---

    # 1. Critical HP: If HP is very low, bid aggressively to survive
    if my_status['hp'] <= 2:
        # Bid very high, slightly above Alex's potential high bid, capped by budget
        # Add a buffer to ensure winning
        return min(my_status['budget'], max(DAILY_SALARY * 1.2, alex_yesterday_bid + 10))

    # 2. High competition due to scarce supply (1 or 0 potential winners)
    if potential_winners <= 1:
        if alex_yesterday_bid > DAILY_SALARY * 0.7: # Alex is a strong bidder
            # Bid slightly higher than Alex's previous bid to secure water
            bid = max(base_bid, alex_yesterday_bid + 5)
            return min(my_status['budget'], bid)
        else:
            # Alex is not bidding high, but supply is still scarce. Bid firmly.
            return min(my_status['budget'], DAILY_SALARY * 1.0)

    # 3. Moderate competition / Abundant supply (2 or more potential winners)
    else:
        if alex_yesterday_bid > DAILY_SALARY * 0.8 and my_status['hp'] <= 4:
            # Alex is still strong, and my HP is not perfectly healthy. Be competitive.
            return min(my_status['budget'], max(base_bid, alex_yesterday_bid + 2))
        elif my_status['hp'] <= 4:
            # My HP is a bit low, but supply is good. Bid reasonably to stay healthy.
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        else:
            # Healthy HP, abundant supply. Can bid more conservatively.
            return min(my_status['budget'], DAILY_SALARY * 0.75)

    # Fallback (should ideally not be reached)
    return min(my_status['budget'], base_bid)
